#include "KS/SRC/ks/FEMenu_shared.h"

class ControllerFrontEnd : public FEGraphicalMenu {
    PanelQuad *quads[9];

public:
    virtual void Load();
};

void ControllerFrontEnd::Load()
{
    LoadPanel();
    for (int i = 0; i < 9; i++)
        quads[i] = GetPointer(("box_0" + stringx(i + 1)).data());
}
